        w.u32(u('fileUnknown', 1));
        w.block(blocks.pages);
        w.block(blocks.shaderGroup);
        w.block(blocks.skeleton);
        writeVec3(w, d.boundingCenter);
        w.f32(d.boundingSphereRadius);
        writeVec3(w, d.boundingBoxMin);
        w.u32(u('unknown3C', 0x7f800001));
        writeVec3(w, d.boundingBoxMax);
        w.u32(u('unknown4C', 0x7f800001));
