        const h = Math.max(0.01, size[2]);
        const faces = [];
        let second = false;
        const quad = (points, normal, uvs) => faces.push(second ? { points, normal, uvs, accent: true } : { points, normal, uvs });
        const accent = (make) => {
            second = true;
            make();
            second = false;
        };
