                if (!zone || !zone.sphere) continue;
                const radius = Number(zone.sphere[3]) || 0;
                const d = Math.hypot(best.local[0] - zone.sphere[0], best.local[1] - zone.sphere[1], best.local[2] - zone.sphere[2]);
                if (!(radius > 0) || d > radius) continue;
                const range = Number(zone.range) || 0;
                const edge = range > 0 ? Math.max(0, Math.min(1, (radius - d) / range)) : 1;
                const name = typeof zone.name === 'number' ? zone.name >>> 0 : MM.joaat(String(zone.name || '')) >>> 0;
