                    interior: true, key: record.name + '#' + e.index, map: record.name, index: e.index, position: e.position.slice(0, 3), hash: e.hash >>> 0, lodDist: 0, kids: 0, kidDist: 0, parent: null,
                    parentIndex: e.parentIndex === undefined ? -1 : e.parentIndex, external: !!e.parentInOtherFile,
