                numChildren: e.numChildren | 0, flags: e.flags >>> 0, scripted: record.scripted,
                box: found && found.box ? found.box : null, asset: found ? found.asset || 'ydr' : '', dictionary: found ? found.dictionary || '' : '', textures: found ? found.textures || '' : '',
                door: !!(found && found.door), same: sameKey(e.hash, e.position), kids: 0, kidDist: 0, parent: null,
                types: found && found.types ? String(found.types).toLowerCase() : '', archFlags: found && found.flags ? found.flags >>> 0 : 0, timed: false, timeFlags: 0,
                tint: Number(e.tintValue) > 0 ? Number(e.tintValue) | 0 : 0, ownChildDist: Number(e.childLodDist), special: found && found.special ? found.special : 0
