                    key: record.name + '#' + e.index, name: model ? String(model).toLowerCase() : '', hash: e.hash >>> 0, map: record.name, index: e.index,
                    position: e.position.slice(0, 3), quaternion: MM.coords.worldQuaternion(e.rotation, false), scale,
                    lodLevel: e.lodLevel, lodDist: e.lodDist, parentIndex: e.parentIndex, external: !!e.parentInOtherFile, parentMap: e.parentInOtherFile ? record.parent : '',
                    numChildren: e.numChildren | 0, flags: e.flags >>> 0, scripted: record.scripted,
                    box, asset: found ? found.asset || 'ydr' : '', dictionary: found ? found.dictionary || '' : '', textures: found ? found.textures || '' : '',
                    door: !!(found && found.door)
