        if (typeof value.parent === 'string' && typeof value.child === 'string') addParent(out, value.parent, value.child);
        for (const key of Object.keys(value)) if (value[key] && typeof value[key] === 'object' && !ArrayBuffer.isView(value[key])) objectParents(value[key], out, depth + 1);
