    function objectBox(name) {
        const key = String(name || '').toLowerCase();
        const measured = OBJECT_BOXES[key];
        const b = measured || OBJECT_ROUGH[key];
        return b ? { min: [b[0], b[1], b[2]], max: [b[3], b[4], b[5]], rough: !measured } : null;
    }

    function exampleKit(p, height) {
        const F = MM.mlofaces;
        const use = (id, builtin) => {
            if (!p.materials.some((m) => m.id === id)) p.materials.push(material(id, builtin));
            return id;
        };
        const room = (name, x, y, w, d, values) => addRoom(p, Object.assign({ name, points: rectangle(x, y, w, d), height: height || 3 }, values));
        const side = (r, name, at) => {
            const q = r.points;
            if (name === 's') return { room: r.id, edge: 0, offset: at - q[0][0] };
            if (name === 'e') return { room: r.id, edge: 1, offset: at - q[1][1] };
            if (name === 'n') return { room: r.id, edge: 2, offset: q[2][0] - at };
            return { room: r.id, edge: 3, offset: q[3][1] - at };
        };
        const open = (r, name, at, values) => addOpening(p, Object.assign(side(r, name, at), values));
        const hang = (r, name, at, id, values, design) => addWallItem(p, 'picture', Object.assign(side(r, name, at), values, { design: Object.assign({ id }, design) }));
        const put = (kind, x, y, size, turn, materialId, extra) => {
            const block = Object.assign({ id: uid(p, 'block'), kind, position: [x, y, 0], rotation: [0, 0, turn || 0], size, material: materialId || 'walls', collision: true }, extra);
            p.blocks.push(block);
            return block;
        };
        const lay = (id, x, y, width, length, turn, design) => put('plane', x, y, [width, length, 0.01], turn, 'walls', { collision: false, design: Object.assign({ id, text: '', colour: '', back: '', seed: 0 }, design) });
        const band = (r, materialId, top) => {
            if (!F) return;
            for (let edge = 0; edge < r.points.length; edge++) F.addPatch(p, { room: r.id, on: edge, z0: 0, z1: top || 1.05, material: materialId });
        };
        const lamp = (x, y, z, values, shade) => {
            const kind = shade || 'panel';
            const size = kind === 'tube' ? [1.5, 0.16] : kind === 'round' ? [0.4, 0.4] : kind === 'spot' ? [0.16, 0.16] : kind === 'long' ? [1.2, 0.3] : [0.6, 0.6];
            put('plane', x, y, [size[0], size[1], 0.01], 0, 'walls', { position: [x, y, z], rotation: [180, 0, 0], collision: false, glow: 2, design: { id: kind === 'tube' ? 'light_tube' : kind === 'round' || kind === 'spot' ? 'light_round' : 'light_panel', text: '', colour: kind === 'round' ? '#fff0d6' : '#ffffff', back: kind === 'tube' ? '#9aa0a8' : '#c9ccd1', seed: 0 } });
            return addLight(p, Object.assign({ position: [x, y, z - 0.15] }, values));
        };
        const round = (v) => Math.round(v * 1000) / 1000;
        const headingOf = (degrees) => {
            const h = ((Math.round((Number(degrees) || 0) * 100) / 100) % 360 + 360) % 360;
            return h > 180 ? h - 360 : h;
        };
        const boxFor = (model) => objectBox(model) || { min: [-0.25, -0.25, 0], max: [0.25, 0.25, 0.5] };
        let home = null;
        const within = (r) => {
            home = r || null;
        };
        const set = (model, x, y, z, heading) => {
            const object = { id: uid(p, 'object'), model, position: [round(x), round(y), round(z)], rotation: [0, 0, headingOf(heading)], entitySet: '' };
            if (home && Number(home.floor)) object.room = home.id;
            const own = EXAMPLE_OWN[model];
            if (own) {
                object.fallback = own.fallback;
                if (own.turn) object.fallbackTurn = own.turn;
                if (own.lift) object.fallbackLift = own.lift;
                if (own.shift) object.fallbackShift = own.shift.slice(0, 2);
                if (own.pack) object.pack = own.pack;
            }
            p.objects.push(object);
            return object;
        };
        const stand = (model, x, y, heading, floor) => set(model, x, y, (floor || 0) - boxFor(model).min[2], heading);
        const rest = (model, x, y, top, heading) => set(model, x, y, top - boxFor(model).min[2], heading);
        const group = (x, y, heading, floor, items) => {
            const angle = (Number(heading) || 0) * Math.PI / 180;
            const c = Math.cos(angle);
            const s = Math.sin(angle);
            return items.map((item) => {
                const wx = x + item[1] * c - item[2] * s;
                const wy = y + item[1] * s + item[2] * c;
                const turn = (Number(heading) || 0) + (item[4] || 0);
                return item[3] === null || item[3] === undefined ? stand(item[0], wx, wy, turn, floor) : rest(item[0], wx, wy, (floor || 0) + item[3], turn);
            });
        };
        const facing = (model, x, y, towardX, towardY, floor) => stand(model, x, y, Math.atan2(-(x - towardX), y - towardY) * 180 / Math.PI, floor);
        const WALL_TURNS = { s: 180, n: 0, w: 90, e: -90 };
        const against = (r, wall, at, model, options) => {
            const o = options || {};
            const q = r.points;
            const b = boxFor(model);
            const face = EXAMPLE_FACES[model] || '-y';
            const back = face === '+x' ? -b.min[0] : face === '+y' ? -b.min[1] : face === '-x' ? b.max[0] : b.max[1];
            const turn = face === '+x' ? -90 : face === '+y' ? 180 : face === '-x' ? 90 : 0;
            const off = (o.gap === undefined ? (o.z === undefined ? 0.05 : 0.01) : o.gap) + back;
            const x = wall === 'w' ? q[0][0] + off : wall === 'e' ? q[1][0] - off : at;
            const y = wall === 's' ? q[0][1] + off : wall === 'n' ? q[2][1] - off : at;
            const heading = WALL_TURNS[wall] + turn + (o.turn || 0);
            const floor = o.floor === undefined ? Number(r.floor) || 0 : o.floor;
            const before = home;
            home = r;
            const made = o.ceiling ? set(model, x, y, floor + r.height - b.max[2], heading) : o.z === undefined ? stand(model, x, y, heading, floor) : set(model, x, y, floor + o.z, heading);
            home = before;
            return made;
        };
        const row = (r, wall, from, step, count, model, options) => {
            const made = [];
            for (let i = 0; i < count; i++) made.push(against(r, wall, from + step * i, model, options));
            return made;
        };
        const under = (r, x, y, model, heading) => set(model, x, y, (Number(r.floor) || 0) + r.height - boxFor(model).max[2], heading);
        const boards = (block) => {
            const size = block.size;
            const count = Math.max(2, Math.min(12, Math.round(Number(block.count) || size[2] / 0.4) + 1));
            const tops = [];
            for (let i = 0; i < count; i++) tops.push(round((block.position[2] || 0) + (size[2] - 0.03) * i / (count - 1) + 0.03));
            return tops;
        };
        const onto = (block, across, depth, top, model, turn) => {
            const angle = ((block.rotation || [0, 0, 0])[2] || 0) * Math.PI / 180;
            const c = Math.cos(angle);
            const s = Math.sin(angle);
            return rest(model, block.position[0] + across * c - depth * s, block.position[1] + across * s + depth * c, top, ((block.rotation || [0, 0, 0])[2] || 0) + (turn || 0));
        };
        return { use, room, side, open, hang, put, lay, band, lamp, set, stand, rest, group, facing, against, row, under, boards, onto, boxFor, within };
    }

