        lines.push('This resource replaces the game\'s vehicle "' + vehicle.name + '" for everyone on the server. The model files are the game\'s own with one change:');
        lines.push('the body paint has a place for a livery picture now, and the texture files hold ' + count + ' livery picture' + (count === 1 ? '' : 's') + ' (' + vehicle.made.prefix + '1' + (count > 1 ? ' to ' + vehicle.made.prefix + count : '') + ').');
