        if (b[0] === 0x52 && b[1] === 0x49 && b[2] === 0x46 && b[3] === 0x46 && b.length > 12 && b[8] === 0x57 && b[9] === 0x45 && b[10] === 0x42 && b[11] === 0x50) return 'webp';
        if (b[0] === 0x42 && b[1] === 0x4D) return 'bmp';
        if (b[0] === 0x44 && b[1] === 0x44 && b[2] === 0x53 && b[3] === 0x20) return 'dds';
        if (b[0] === 0x47 && b[1] === 0x49 && b[2] === 0x46) return 'gif';
        if (b[0] === 0x52 && b[1] === 0x53 && b[2] === 0x43 && b[3] === 0x37) return 'rsc';
        if (b[0] === 0x46 && b[1] === 0x58 && b[2] === 0x41 && b[3] === 0x50) return 'escrow';
